function UIOutDoorMainDialog:FillSelf()
    self:FillBtns()
end

function UIOutDoorMainDialog:FillBtns()
    for k, v in pairs(self._btnData) do
        local btnGo = self.ButtonGroup.transform:Find("Button"..checkNumber(v.id))
        if btnGo then
            GameUtils.RefeshSystemToggleId(btnGo, v.systemToggleId)
            local scr = CfUtils.GetLuaScr(btnGo, UIOutDoorMainBtnNode)
            if scr then
                scr:Refresh(v, k)
            end
        end
    end
end

---MainMenuAction
---@param id number 打开对话框的id
---@param excludeDialogs table 要关闭的列表的逻辑
function UIOutDoorMainDialog:OpenDialogAction(id, excludeDialogs, par)
    if checkNumber(KCookie.Get(Constants.IsOpnePageing)) == 1 then
        return
    end
    KCookie.Set(Constants.IsOpnePageing, 1)
    UIRaycastBlocker:AddCondition("OpenDialogAction")
    return cs_coroutine.start(function()
        xTry(function()
            coroutine.yield(UIModule.OpenDialog({ id = id, parameters = par}, checkTable(excludeDialogs)))
            UIRaycastBlocker:RemoveCondition("OpenDialogAction")
            KCookie.Set(Constants.IsOpnePageing, 0)
        end, function()
            UIRaycastBlocker:RemoveCondition("OpenDialogAction")
            KCookie.Set(Constants.IsOpnePageing, 0)
        end)
    end)
end

